import{_ as r,C as c,o as i,c as d,a5 as a,j as n,E as s}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":".NET 垃圾回收：分代、标记压缩与触发","description":"本页回答三个问题：托管堆如何分配和回收内存，分代机制如何降低 GC 成本，GC 何时触发以及如何影响延迟。类型布局见类型布局与内存。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"csharp/02-dotnet-runtime/chapter-03-gc.md","filePath":"csharp/02-dotnet-runtime/chapter-03-gc.md"}'),l={name:"csharp/02-dotnet-runtime/chapter-03-gc.md"},h={"data-src-line":"27","data-src-file":"csharp/02-dotnet-runtime/chapter-03-gc.md"};function p(o,t,m,g,u,f){const e=c("SvgDiagram");return i(),d("div",null,[t[0]||(t[0]=a('<h1 id="net-垃圾回收-分代、标记压缩与触发" tabindex="-1" data-src-line="2" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">.NET 垃圾回收：分代、标记压缩与触发 <a class="header-anchor" href="#net-垃圾回收-分代、标记压缩与触发" aria-label="Permalink to &quot;.NET 垃圾回收：分代、标记压缩与触发&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">本页回答三个问题：托管堆如何分配和回收内存，分代机制如何降低 GC 成本，GC 何时触发以及如何影响延迟。类型布局见<a href="./chapter-02-type-layout-memory.html">类型布局与内存</a>。</p><h2 id="_1-托管堆与分配" tabindex="-1" data-src-line="6" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">1. 托管堆与分配 <a class="header-anchor" href="#_1-托管堆与分配" aria-label="Permalink to &quot;1. 托管堆与分配&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">托管对象在托管堆上分配。堆上的分配只移动一个指针（分配指针），成本远低于传统 <code>malloc</code> 的碎片管理：</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 在托管堆分配</span></span></code></pre></div><p data-src-line="14" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">对象不再被任何引用可达时，GC 会回收它。可达性从「根」出发追踪：栈上的局部变量、静态字段、寄存器等是根，从根能到达的对象都是存活的。</p><h2 id="_2-分代回收" tabindex="-1" data-src-line="16" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">2. 分代回收 <a class="header-anchor" href="#_2-分代回收" aria-label="Permalink to &quot;2. 分代回收&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">GC 假设「新对象更可能早死」，把堆分为三代：</p><table tabindex="0"><thead data-src-line="20" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><tr data-src-line="20" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><th style="text-align:left;">代</th><th style="text-align:left;">内容</th><th style="text-align:left;">回收频率与成本</th></tr></thead><tbody data-src-line="22" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><tr data-src-line="22" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><td style="text-align:left;">Gen0</td><td style="text-align:left;">新分配的对象</td><td style="text-align:left;">最频繁，最便宜</td></tr><tr data-src-line="23" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><td style="text-align:left;">Gen1</td><td style="text-align:left;">从 Gen0 幸存的对象</td><td style="text-align:left;">次频繁</td></tr><tr data-src-line="24" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><td style="text-align:left;">Gen2</td><td style="text-align:left;">长期存活的对象</td><td style="text-align:left;">最少，最贵</td></tr><tr data-src-line="25" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><td style="text-align:left;">LOH</td><td style="text-align:left;">大对象（约 85KB 以上）</td><td style="text-align:left;">随 Gen2 回收</td></tr></tbody></table>',9)),n("p",h,[s(e,{src:"/csharp/02-dotnet-runtime-chapter-03-gc-generations.svg",alt:"分代回收：新对象从 Gen0 开始，存活后逐代晋升到 Gen1、Gen2，大对象直接进入 LOH"})]),t[1]||(t[1]=a('<p data-src-line="29" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">图中文字等价于：新对象从 Gen0 开始，Gen0 回收后存活的对象晋升到 Gen1，再晋升到 Gen2；大对象直接进入 LOH，随 Gen2 一起回收。</p><p data-src-line="31" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">Gen0 回收只扫描少量新对象，很快。存活下来的对象晋升到下一代；反复晋升到 Gen2 的对象被视为长期存活，很少再扫描。这使 GC 把成本集中在「短命对象」上，避免每次都扫描整个堆。</p><p data-src-line="33" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">大对象（约 85KB 以上）直接进入 LOH（Large Object Heap），因为复制大对象成本高，LOH 不压缩（.NET 起才在需要时提供压缩），可能产生碎片。</p><h2 id="_3-标记-压缩" tabindex="-1" data-src-line="35" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">3. 标记-压缩 <a class="header-anchor" href="#_3-标记-压缩" aria-label="Permalink to &quot;3. 标记-压缩&quot;">​</a></h2><p data-src-line="37" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">GC 的核心算法是标记-压缩（mark-compact）：</p><ol data-src-line="39" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><li data-src-line="39" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><strong>标记</strong>：从根出发追踪可达对象，标记为存活。</li><li data-src-line="40" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><strong>压缩</strong>：把存活对象向一端移动，消除碎片，更新引用。</li><li data-src-line="41" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><strong>清理</strong>：回收未标记的内存。</li></ol><p data-src-line="43" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">压缩让后续分配仍是简单的指针移动。代价是移动对象时要暂停应用线程（除非是并发/后台 GC，见下）。</p><h2 id="_4-暂停与并发" tabindex="-1" data-src-line="45" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">4. 暂停与并发 <a class="header-anchor" href="#_4-暂停与并发" aria-label="Permalink to &quot;4. 暂停与并发&quot;">​</a></h2><p data-src-line="47" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">GC 的标记-压缩通常需要短暂暂停应用线程（stop-the-world）。为降低延迟，.NET 提供：</p><ul data-src-line="49" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><li data-src-line="49" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><strong>后台（concurrent）GC</strong>：Gen2 的标记大部分与应用并发执行，只在压缩等阶段短暂暂停。默认在工作站 GC 下对 Gen2 启用。</li><li data-src-line="50" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><strong>工作站 GC vs 服务器 GC</strong>：工作站 GC 为低延迟桌面场景优化，服务器 GC 为高吞吐的多核服务端场景优化，为每个逻辑处理器分配独立堆和 GC 线程。</li></ul><p data-src-line="52" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">选择哪种通过配置控制。服务端默认倾向服务器 GC，桌面默认工作站 GC。</p><h2 id="_5-gc-何时触发" tabindex="-1" data-src-line="54" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">5. GC 何时触发 <a class="header-anchor" href="#_5-gc-何时触发" aria-label="Permalink to &quot;5. GC 何时触发&quot;">​</a></h2><p data-src-line="56" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">GC 在以下时机触发，而不是由开发者显式调用：</p><ul data-src-line="58" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><li data-src-line="58" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">Gen0 堆空间不足时。</li><li data-src-line="59" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">分配大对象需要空间时。</li><li data-src-line="60" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">系统内存压力大时。</li><li data-src-line="61" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">显式调用 <code>GC.Collect()</code>（生产代码应避免，除非确知后果）。</li></ul><p data-src-line="63" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">开发者几乎不应手动触发 GC。<code>GC.Collect()</code> 会强制回收，可能打断正常的分代节奏，造成不必要的暂停。正确的做法是减少分配（见下文），让 GC 自然工作。</p><h2 id="_6-减少-gc-压力的手段" tabindex="-1" data-src-line="65" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">6. 减少 GC 压力的手段 <a class="header-anchor" href="#_6-减少-gc-压力的手段" aria-label="Permalink to &quot;6. 减少 GC 压力的手段&quot;">​</a></h2><p data-src-line="67" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">GC 问题表现为频繁回收、长暂停或内存持续增长。常见的减少分配手段：</p><ul data-src-line="69" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><li data-src-line="69" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">用值类型替代大量小引用对象（见<a href="./chapter-02-type-layout-memory.html">类型布局与内存</a>）。</li><li data-src-line="70" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">用 <code>Span&lt;T&gt;</code>/<code>Memory&lt;T&gt;</code> 避免缓冲区复制。</li><li data-src-line="71" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">复用对象（对象池），而不是反复创建。</li><li data-src-line="72" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">避免装箱：泛型和值类型已消除大部分装箱，警惕把值类型赋给 <code>object</code> 或接口。</li></ul><p data-src-line="74" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">但先测量再优化。用 <code>dotnet-counters</code>、<code>dotnet-trace</code> 观察分配速率和 GC 停顿（见<a href="./../07-diagnostics/">诊断</a>），确认 GC 是真实瓶颈后再动手。</p><h2 id="_7-后续阅读" tabindex="-1" data-src-line="76" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">7. 后续阅读 <a class="header-anchor" href="#_7-后续阅读" aria-label="Permalink to &quot;7. 后续阅读&quot;">​</a></h2><ul data-src-line="78" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><li data-src-line="78" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><a href="./chapter-02-type-layout-memory.html">类型布局与内存</a>解释分配如何产生。</li><li data-src-line="79" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><a href="./chapter-04-jit-aot.html">JIT 与 AOT</a>解释编译模式如何影响启动与内存。</li><li data-src-line="80" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><a href="./chapter-05-unmanaged-interop.html">非托管互操作</a>解释非托管内存为何不受 GC 管理。</li><li data-src-line="81" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><a href="./../07-diagnostics/">诊断</a>了解如何测量分配与 GC。</li></ul><blockquote data-src-line="83" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md"><p data-src-line="83" data-src-file="csharp/02-dotnet-runtime/chapter-03-gc.md">本页的技术边界按 .NET 10 / C# 14 核对；分代 GC 与 LOH 的阈值随运行时版本演进，约 85KB 是常见参考值。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/" target="_blank" rel="noreferrer">.NET 文档</a>、<a href="https://learn.microsoft.com/en-us/dotnet/standard/garbage-collection/fundamentals" target="_blank" rel="noreferrer">GC 基础</a>。</p></blockquote>',22))])}const _=r(l,[["render",p]]);export{k as __pageData,_ as default};
